    12→function main(): void {
    13→  const args = process.argv.slice(2);
    14→
    15→  if (args.length === 0 || args[0] === "--help") {
    16→    console.log("FreeLang v4 — AI-First Programming Language");
    17→    console.log("Usage: freelang <file.fl> [options]");
    18→    console.log("");
    19→    console.log("Options:");
    20→    console.log("  --no-check   타입 체크 건너뛰기");
    21→    console.log("  --dump-bc    바이트코드 덤프");
    22→    console.log("  --dump-ir    IR(중간 표현) 덤프");
    23→    console.log("  --use-ir     IR 경로로 컴파일");
    24→    console.log("  --help       도움말");
    25→    process.exit(0);
    26→  }
    27→
    28→  const file = args[0];
    29→  const noCheck = args.includes("--no-check");
    30→  const dumpBc = args.includes("--dump-bc");
    31→  const dumpIr = args.includes("--dump-ir");
    32→  const useIr = args.includes("--use-ir") || dumpIr;
    33→
    34→  // 파일 읽기
    35→  let source: string;
    36→  try {
    37→    source = fs.readFileSync(file, "utf-8");
    38→  } catch {
    39→    console.error(`error: cannot read file '${file}'`);
    40→    process.exit(1);
    41→  }
    42→
    43→  // 1. Lexer
    44→  const { tokens, errors: lexErrors } = new Lexer(source).tokenize();
    45→  if (lexErrors.length > 0) {
    46→    for (const e of lexErrors) {
    47→      console.error(`${file}:${e.line}: lex error: ${e.message}`);
    48→    }
    49→    process.exit(1);
    50→  }
    51→
    52→  // 2. Parser
    53→  const { program, errors: parseErrors } = new Parser(tokens).parse();
    54→  if (parseErrors.length > 0) {
    55→    for (const e of parseErrors) {
    56→      console.error(`${file}:${e.line}: parse error: ${e.message}`);
    57→    }
    58→    process.exit(1);
    59→  }
    60→
    61→  // 3. TypeChecker (optional)
    62→  if (!noCheck) {
    63→    const checkErrors = new TypeChecker().check(program);
    64→    if (checkErrors.length > 0) {
    65→      for (const e of checkErrors) {
    66→        console.error(`${file}:${e.line}: type error: ${e.message}`);
    67→      }
    68→      process.exit(1);
    69→    }
    70→  }
    71→
    72→  // 4. Compiler (IR 경로 vs 기존 경로)
    73→  let chunk;
    74→  if (useIr) {
    75→    const irProg = new IRGen().generate(program);  // AST → IR
    76→    if (dumpIr) {
    77→      console.log(JSON.stringify(irProg, null, 2));
    78→      process.exit(0);
    79→    }
    80→    chunk = new Compiler().compileIR(irProg);      // IR → Chunk
    81→  } else {
    82→    chunk = new Compiler().compile(program);       // 기존 경로 유지
    83→  }
    84→
    85→  if (dumpBc) {
    86→    console.log(`--- bytecode (${chunk.code.length} bytes, ${chunk.functions.length} functions) ---`);
    87→    console.log(`constants: ${JSON.stringify(chunk.constants)}`);
    88→    for (const fn of chunk.functions) {
    89→      console.log(`fn ${fn.name}(arity=${fn.arity}) @ offset ${fn.offset}`);
    90→    }
    91→    process.exit(0);
    92→  }
    93→
    94→  // 5. VM 실행
    95→  const { output, error } = new VM().run(chunk);
    96→
    97→  for (const line of output) {
    98→    console.log(line);
    99→  }
   100→
